source='''def transform(grid):
    # Match each framed 3x3 mask on the left to the colored 3x3 object on the right.
    h, w = len(grid), len(grid[0])
    frame = next(v for v in set(sum(grid, [])) if v != 0)
    shapes = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in (0, frame):
                shapes.setdefault(color, set()).add((r, c))
    normalized = {}
    for color, cells in shapes.items():
        r0 = min(r for r, c in cells)
        c0 = min(c for r, c in cells)
        normalized[color] = {(r-r0, c-c0) for r, c in cells}

    out = [row[:5] for row in grid]
    # Horizontal separators divide the left strip into 4-row steps; each tile is 5x5.
    for start in range(0, h, 4):
        if start + 4 >= h:
            break
        mask = {(r-1, c-1) for r in range(1, 4) for c in range(1, 4)
                if grid[start+r][c] == 0}
        for color, shape in normalized.items():
            if shape == mask:
                for r, c in mask:
                    out[start+1+r][1+c] = color
                break
    return out
